import sys
from pysat.solvers import Glucose4

V = 19
E_target = 26

# We can use a SAT solver with a simpler encoding for girth >= 7.
# A graph has girth >= 7 iff for every vertex v, the BFS tree up to depth 3 has no cross edges,
# except possibly at depth 3.
# Actually, girth >= 7 means there is no cycle of length 3, 4, 5, 6.
# Let A be the adjacency matrix.
# Tr(A^3) = 0
# Tr(A^4) = 0
# Tr(A^5) = 0
# Tr(A^6) = 0
# This is hard to encode in SAT.

# Let's use a constraint solver or just a simple backtracking search in C++ / PyPy, but we only have Python.
# Let's write a fast C-like backtracking in Python.
code = """
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>

#define V 19
#define E_TARGET 26

uint32_t adj[V];
int edges = 0;

int has_cycle_up_to_6(int u, int v) {
    // We are about to add edge (u, v).
    // We need to check if there is a path of length <= 5 between u and v.
    // BFS from u up to depth 5.
    uint32_t visited = (1 << u);
    uint32_t q[V];
    int dist[V];
    int head = 0, tail = 0;

    q[tail] = u;
    dist[tail++] = 0;

    while (head < tail) {
        int curr = q[head];
        int d = dist[head++];

        if (d == 5) continue;

        uint32_t neighbors = adj[curr];
        while (neighbors) {
            int nxt = __builtin_ctz(neighbors);
            neighbors &= neighbors - 1;

            if (nxt == v) return 1; // Found a path of length d+1 <= 5

            if (!(visited & (1 << nxt))) {
                visited |= (1 << nxt);
                q[tail] = nxt;
                dist[tail++] = d + 1;
            }
        }
    }
    return 0;
}

int solve(int u, int v) {
    if (edges == E_TARGET) {
        return 1;
    }
    if (u == V) return 0;

    int next_u = u, next_v = v + 1;
    if (next_v == V) {
        next_u = u + 1;
        next_v = next_u + 1;
    }

    // Pruning: if remaining possible edges + current edges < E_TARGET, return 0
    int remaining_pairs = (V - u) * (V - u - 1) / 2 - (v - u);
    if (edges + remaining_pairs < E_TARGET) return 0;

    // Try adding edge (u, v)
    if (!has_cycle_up_to_6(u, v)) {
        adj[u] |= (1 << v);
        adj[v] |= (1 << u);
        edges++;

        if (solve(next_u, next_v)) return 1;

        adj[u] &= ~(1 << v);
        adj[v] &= ~(1 << u);
        edges--;
    }

    // Try not adding edge (u, v)
    if (solve(next_u, next_v)) return 1;

    return 0;
}

int main() {
    if (solve(0, 1)) {
        printf("SAT\\n");
        for (int i = 0; i < V; i++) {
            for (int j = i + 1; j < V; j++) {
                if (adj[i] & (1 << j)) {
                    printf("%d %d\\n", i, j);
                }
            }
        }
    } else {
        printf("UNSAT\\n");
    }
    return 0;
}
"""

