# Let's write a fast backtracking in Python.
def solve():
    V = 19
    E_TARGET = 26

    adj = [0] * V
    edges = 0

    def has_cycle_up_to_6(u, v):
        visited = 1 << u
        q = [u]
        dist = [0]
        head = 0

        while head < len(q):
            curr = q[head]
            d = dist[head]
            head += 1

            if d == 5:
                continue

            neighbors = adj[curr]
            while neighbors:
                nxt = (neighbors & -neighbors).bit_length() - 1
                neighbors &= neighbors - 1

                if nxt == v:
                    return True

                if not (visited & (1 << nxt)):
                    visited |= (1 << nxt)
                    q.append(nxt)
                    dist.append(d + 1)
        return False

    def backtrack(u, v, edges):
        if edges == E_TARGET:
            return True
        if u == V:
            return False

        next_u = u
        next_v = v + 1
        if next_v == V:
            next_u = u + 1
            next_v = next_u + 1

        remaining_pairs = (V - u) * (V - u - 1) // 2 - (v - u)
        if edges + remaining_pairs < E_TARGET:
            return False

        if not has_cycle_up_to_6(u, v):
            adj[u] |= (1 << v)
            adj[v] |= (1 << u)
            if backtrack(next_u, next_v, edges + 1):
                return True
            adj[u] &= ~(1 << v)
            adj[v] &= ~(1 << u)

        if backtrack(next_u, next_v, edges):
            return True

        return False

    if backtrack(0, 1, 0):
        print("SAT")
        for i in range(V):
            for j in range(i + 1, V):
                if adj[i] & (1 << j):
                    print(f"{i} {j}")
    else:
        print("UNSAT")

solve()
